package adhoc

import (
	_ "embed"
	"testing"

	"github.com/tetratelabs/wazero"
	"github.com/tetratelabs/wazero/api"
	"github.com/tetratelabs/wazero/experimental"
	"github.com/tetratelabs/wazero/internal/platform"
	"github.com/tetratelabs/wazero/internal/testing/require"
)

// shadowFrameRegallocWasm was generated by the following:
//
//	cd testdata; wat2wasm --enable-all shadow_frame_regalloc.wat
//
//go:embed testdata/shadow_frame_regalloc.wasm
var shadowFrameRegallocWasm []byte

// TestShadowFrameRegalloc is a regression test for a wazevo bug where
// ShadowFrameEnter shared one address mode between the load and the store of
// execCtx.shadowRefsTop. Allocating the load rewrote the shared base register,
// so the store no longer used the execution context, and under register
// pressure the counter took its register: the store went to a wild address and
// crashed the Go runtime.
func TestShadowFrameRegalloc(t *testing.T) {
	if !platform.CompilerSupported() {
		t.Skip()
	}
	r := wazero.NewRuntimeWithConfig(testCtx, wazero.NewRuntimeConfigCompiler().
		WithCoreFeatures(api.CoreFeaturesV2|experimental.CoreFeaturesExceptionHandling))
	defer r.Close(testCtx)

	mod, err := r.Instantiate(testCtx, shadowFrameRegallocWasm)
	require.NoError(t, err)

	res, err := mod.ExportedFunction("entry").Call(testCtx)
	require.NoError(t, err)
	require.Equal(t, uint32(26), api.DecodeU32(res[0])) // $many's last param, read back from memory
}
